INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1531304-ics108', 'stk-user12093', 'ICS 108', 'info', '{"desc": "توصيف المقرر\nالمقرر ضمن المقررات المستحدثة للخطة الجديدة وأول مرة يُدرَّس ترم 202 وهو عبارة عن ICS 102 + ICS 201 -سابقا-من حيث المحتوى والمواضيع أما بالنسبة لحيثيّة خطة التخصص ف ICS 104 بدلا من ICS 102 فتصبح مادة واحدة-ICS 102-في الفرشمن سابقا مقابل ثلاث مواد-ICS 104 + (ICS 102 + ICS 201 = ICS 108)-في الفرشمن الآن. المقرر له لابان كل أسبوع، بعد كل محاضرة Lecture لاب عمّا أخذته في المحاضرة. المقرر دسم ومواضيعه كثيرة ومترابطة وبعضها يستغرق تصوّره أو معرفة الفائدة منه وقتا خصوصا عند الانتهاء من أول جزء وما بعده من المقرر لذلك ينبغي المراجعة والمذاكرة أول بأول وإلّا تراكمت عليك الدروس. المقرر فيه بروجكت وستطبق فيه غالب ما أخذته وستلاحظ وقتها ترابط مواضيع المقرر. هذا سيلابس المقرر ترم 202: 202ICS108Syllabus.pdf\n\nالمواضيع التي يغطيها المقرر\nالمواضيع التي يتناولها الكورس هي: أساسيات الجافا وهذا الجزء عبارة عن ICS 102-سابقا-والمفترض أنه جزء بسيط لأن الطالب انتهى من ICS 104، مفاهيم الOOP (Object-Oriented Programming) وهي: (Inheritance; Polymorphism; Abstract classes and interfaces)، (Java Fx) GUI ومواضيع أخرى، مثل: Recursion.\n\nجودة المقرر بشكل عام\nالمقرر بشكل عام ممتاز وأجزم أنك ستلاحظ أثره عليك معرفيا بعد الانتهاء منه.\n\nالكتاب المستخدم للمقرر\nالكتاب المقرر للمادة هو: Y. Daniel Liang, “Introduction to Java Programming and Data Structures”, Comprehensive Version, Global Edition, 11th Edition, 2019, Pearson. ويوجد سلايدات مختصرة للكتاب وتكفي عن الكتاب مجملا لكن في بعض المواضيع قد تحتاج للرجوع للكتاب لمزيد إيضاح وتفصيل.\n\nالأسئلة والأمثلة المستخدمة في المقرر\nالمقرر فيه معلومات نظرية كثير وبعض التفاصيل متشابهة مع فروق دقيقة لذلك الأسئلة النظرية ليست بسيطة وتحتاج حفظ، الأسئلة التي تحتاج لكتابة كود مستواها مناسب. تاسكات اللاب ما كانت تغطي جميع المواضيع تفصيليا ومستواها-غالبا-بسيط.", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ics-108-object-oriented-programming/184029/2", "user": "user12093", "ts": 1629198499000, "tid": 184029, "pn": 2}}', 1629198499000, 1794766200, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1534597-ics108', 'stk-tee', 'ICS 108', 'info', '{"desc": "نفس كلام اخوي اللي فوق لكن بازيد عليه كم شغلة…\n\nبعد ماتخلص من ics104 بتدخل على هذي الماده واللي تعتبر اول ماده بالتخصص تقريبا\nافضل شي بالكورس ان التركات والصعوبة اللي كنا نشوفها ب كويزات ومياجر ics104 وواجباتها صارت قليييل جدا بحكم ان الماده مادة تخصص وليست كومن\nهذا شي بيساعدك انك تستمتع بالمادة اكثر\n\nالكورس بتاخذ فيه بالبداية نفس ماخذت ببايثون واللي هي if statements و loops و methods وطريقة كتابتهم بجافا والى اخره واللي بتكون جدا سهله بالنسبة لك بحكم ان الاختلاف الوحيد اللي هي الكلمات اما المفهوم بتكون فاهمهم بics104\nلكن بعدها بتبدا تدخل ب اشياء جديده وبتحتاج تركيز اكثر مثل classes و interfaces و Javafx وهو انك تسوي واجهة برنامج مع ازرار وتحكم بجافا\nبداية الكورس الموضوع بيكون سهل لكن بعدين يحتاج تركيز… في سلبية بسيطة ان الكلاس ساعة وربع وبعدها لاب ساعة وربع لكن طبيعي يصيبك الملل اثناء الكلاس وتفوت بعض الاشياء\n\nالسلايدات تكفي لكن في بعض التفاصيل بالدروس البعيده قد يحتاج انك ترجع للكتاب او اي مصدر عالنت في حال تبي تفهم وتتعمق اكثر\nتاسكات اللابات كانت بسيطة الى متوسطة…\n\nوبالنهاية المقرر بتستفيد منه كثير فنصيحتي لك انك تاخذ الكورس ونيتك انك تستفيد وتستمتع فيه اكثر من انك تعتبره كورس تبي تعديه بس", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ics-108-object-oriented-programming/184029/3", "user": "Tee", "ts": 1654720697000, "tid": 184029, "pn": 3}}', 1654720697000, 1794766200, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-kamina-ics108', 'stk-kamina', 'ICS 108', 'doc', '{"docs": [{"id": "stk-dr-f98305", "n": "Dr. Yahya Garout", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ICS108 LEC - 202\nالتحضير :ما ينادي بالاسماء.\nبس اتوقع كان يستخدم من تيمز بالتحضير بس اتوقع غيب احد حتى لو تاخر او ما حضر\n\nطريقة الشرح كان يشرح باستخدام سلايدات الكتاب يعرضها لنا مع بعض كودات تعطيك فكرة افضل عن الموضوع.\nيعني غالبا بتوصلك المعلومة.\n\nالكويزات :كويزاته وسط تميل للسهولة واغلبها تكون من كويزات الكتاب مع بعض التعديلات.\n\nالمياجر: يوجد ميد واحد, كان وسط بسبب انه كان مبهم شوي والماتيريل ثقيل\n\nالفاينلات :فاينل كان سهل جدا في الجزئيتين البرمجة والخيارات + ما قصروا حذفوا جزئية طيبة من الماتيريل بسبب تقديم الاختبارات.\n\nالقريد النهائي:A+\n\nالصوت:واضح\n\nإضافات :الدكتور كان هو الكوردنيتر للكورس فممكن يتغير الوضع للاترام الثانية,بس ما قصر سهلنا جزئيات الJavafx بأنها تكون موضوع اختبار اللاب والبروجكت.\n\nالدكتور كنت الاحظ انه مشغول وشوي صعب التواصل معه, بحكم انه ماسك كوردنيتر كورسين 201و108 فكان كثيير من الاختبارات والواجبات مبهمة حتى كلمته بليلة قبل الفاينل قال انه لسى ما صحح لاب تست طلاب اللاب حقه مع انه الدكاترة الثانين نزلوا لطلابهم من كثر ما هو مشغول.\n\nعامة لا يفوت الدكتور حبيب جدا ومتعاون ويعيد شرح للمواضيع اللي ما فهمتها وممكن حتى يسهلها لك ان احتجت.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1529911-ics108", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/yahya-garout/98305/24", "user": "Kamina", "ts": 1620486596000, "tid": 98305, "pn": 24}}, {"id": "stk-dr-f99241", "n": "Dr. M Balah", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "(Online)ICS108 LAB - 202\n\nالتحضير: بالبداية كان ينادي الاسامي ويحضرهم بس بعدين صار كل واحد يقله احفظ ترتيبك بالسكشن و ينادي بالرقم ذا.\n\nطريقة الشرح :ما في شرح, بس يقولك وش موضوع اللاب ويقلك عن بعض الميثودز او التنبيهات اللي ما يبغى يشوفها من الطالب.\nلانه بعض الاحيان كان يزود بعض الاشياء زيادة عن المطلوب باللاب.\n\nالكويزات :تاسكات تسلمها وقت الكلاس لكن بعد فترة صار يمددها لللاب اللي بعده ,كان اتوقع تغيير من الكوردنيتر مب منه.\n\nالمياجر: -\n\nالفاينلات : لاب تست واحد عن JavaFX كان سهل جدا.\n\nالصوت:واضح\n\nالقريد النهائي:A\n\nإضافات :اذا انت كنت ناسخ الكود فممكن انه يسألك عن الكود ويحشرك.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1529933-ics108", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/m-balah/99241/37", "user": "Kamina", "ts": 1620554870000, "tid": 99241, "pn": 37}}]}', 1620486596000, 1794766200, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-mohammed_mag-ics108', 'stk-mohammed_mag', 'ICS 108', 'doc', '{"docs": [{"id": "stk-dr-f118622", "n": "Dr. Adam Salahadin", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ICS 108 -202\n\nالتحضير :\nيحضر تلقائي من التيمز بدون ماينادي الاسامي\n\nطريقة الشرح :\nشرحه كان متوسط نوعا ما لأن الكورس اول مره يَدرس بالجامعه وغالبا اغلب الدكاتره كذا\n\nالكويزات :\nصعبه تقريبا ومشتركه بين كل السكاشن الي منزلين الكورس يعني مب من الدكتور الاساله\n\nالمياجر:\nكومن\nالفاينلات :\nكومن\nالصوت:\nواضح جدا\n\nإضافات :\nالدكتور حبيب جدا ومتساعد ومتفاهم مع الطالب , ويحاول يفهم النقطه بافضل طريقه ممكنه .", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1530008-ics108", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/adam-salahadin/118622/10", "user": "Mohammed_Mag", "ts": 1621499751000, "tid": 118622, "pn": 10}}, {"id": "stk-dr-f183287", "n": "Dr. Khaled Daud", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ICS 108 - LAB -202\n\nالتحضير :\nماينادي اسامي , اتوقع يحضر مع تسليم اللاب نهايه الكلاس ويقولك امشي بدري عادي\n\nطريقة الشرح :\nواضح جدا مايقصر في توصيل المعلومه\n\nالكويزات :\nلايوجد\n\nالمياجر:\nكومن\nالفاينلات :\nكومن\n\nإضافات :", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1530010-ics108", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/khaled-daud/183287/4", "user": "Mohammed_Mag", "ts": 1621500167000, "tid": 183287, "pn": 4}}]}', 1621499751000, 1794766200, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user12093-ics108', 'stk-user12093', 'ICS 108', 'doc', '{"docs": [{"id": "stk-dr-f182632", "n": "Dr. Andri Mirzal", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ICS 108-202-Online\n\nالتحضير:\nنهاية المحاضرة يحضّر، ولا يغيّب يعطي ليت فقط لكن ما عمره فوّت تحضير.\n\nطريقة الشرح:\nيقرأ من السلايدات ويستخدم برنامج الرسام لتوضيح بعض المفاهيم من خلال رسم خريطة ذهنية أو تقسيمات ويفتح إكليبس يشرح الأكواد. كنت أركز معه بداية الترم لكن سحبت عليه بعدين لأن شرحه سيء وممل للأمانة، يبدأ يتكلم من بداية الكلاس بنفس النبرة ولا يوقف إلا على آخر دقيقة بدون أي سؤال ومشاركة مع الطلاب.\n\nالكويزات:\nمقارنة مع بقية الدكاترة لنفس المادة كويزاته كانت صعبة.\n\nالمياجر:\nكومن.\n\nالفاينلات:\nكومن.\n\nالصوت:\nواضح ولهجته تمشي الحال بعيدا عن التهويل.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1531311-ics108", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/andri-mirzal/182632/6", "user": "user12093", "ts": 1629257838000, "tid": 182632, "pn": 6}}, {"id": "stk-dr-f183287", "n": "Dr. Khaled Daud", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ICS 108-202-Online Lab\n\nالتحضير:\nما يحضّر، تسليمك اللاب دلالة على حضورك.\n\nطريقة الشرح:\nممتاز، يشرح إيش المطلوب كل لاب ثم يقول ابدأوا ولو ما فهمت شيء أو نقطة معينة يشرح لك.\n\nالكويزات:\nلا يوجد.\n\nالفاينلات:\nاللاب تيست كان سهل.\n\nالصوت:\nواضح.\n\nإضافات:\nتصحيحه ممتاز ولو عندك خطأ يجعلك تصححه، ولا تفوّت الأوفيس أور لو عندك إشكال. لو جاء لي فرصة أدرس معه بعدين لن أتردد.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1531312-ics108", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/khaled-daud/183287/5", "user": "user12093", "ts": 1629259383000, "tid": 183287, "pn": 5}}]}', 1629257838000, 1794766200, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-posty-ics108', 'stk-posty', 'ICS 108', 'doc', '{"docs": [{"id": "stk-dr-f183287", "n": "Dr. Khaled Daud", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ICS 108 Lab-202\nSWE 206Lab-211\n\nالاشياء الي كان يسويها اونلاين وماصار يسويها حضوري مابذكرها لان من غير شر مابنرجع اونلاين\n\nالتحضير : نص اللاب\nطريقة الشرح : يشرح اللاب ويطول شوي في الشرح ممكن ياخذ حول الساعه من كل لاب علشان الشرح\nالتصحيح: سهل تفلل اللابات عنده\nالقريد النهائي:A\nالصوت: واضح جدا\nإضافات : الدكتور خلوق وعسل ومتساعد جدا اي سؤال تساله في اللاب ماراح يقصر معك، وانتم تسوون اللاب ياخذ لفه على الطلاب ويناقشهم في اللاب والافكار حقت اللاب ويعطيهم نصايح علشان يحسنون من شغلهم", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1532695-ics108", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/khaled-daud/183287/6", "user": "Posty", "ts": 1636487506000, "tid": 183287, "pn": 6}}]}', 1636487506000, 1794766200, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-guest-ics108', 'stk-guest', 'ICS 108', 'doc', '{"docs": [{"id": "stk-dr-f183289", "n": "Dr. Rashad Othman", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "انا استغرب صراحة ان طلابه لحد الان ما كتبوا تقييم عنه، لكن الدكتور رشاد صراحة اعتبره افضل دكتور مر علي خلال حياتي الدراسية كاملة بدون مبالغة، الدكتور على تواصل مع الطلاب على مدار 24 ساعة سواء واتس ولا تيمز ولا ايميل ترسل له سؤال وما يقصر معك فيه ويعطي تمارين اضافية للطالب اللي مهتم بالبرمجة او انه متخصص في كليات الحاسب بشكل عام، الدكتور جدا متعاون مع الطلاب وسوا هيلب سشن قبل الاختبار بيوم من الساعة 3 العصر تقريبا إلى 12 بالليل!! لو حصل لي فرصة انزل عنده ICS 108 بنزل عنده وانا مغمض لو كان كلاسه او لابه 8 العشاء", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1526413-ics108", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/rashad-othman/183289/2", "user": "Guest", "ts": 1603834850000, "tid": 183289, "pn": 2}}]}', 1603834850000, 1794766200, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-omar-12232-ics108', 'stk-omar-12232', 'ICS 108', 'doc', '{"docs": [{"id": "stk-dr-f183289", "n": "Dr. Rashad Othman", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ICS108 - Term 211\n\nالتحضير: مايحضر. مابدا يحضر الا بانهاية الترم بالاب.\n\nالكويزات: مستواهم حلو مو صعبين ولا سهلين.\n\nالشرح: الشرح اسطوري وواضح. يشرح من سلايداته.\n\nالصوت: واضح\n\nنقاط اضافية: الدكتور طيب جداااااا وخلوق ويحب المزح مع الطلاب. يحفظ اسامي كل طلابه ويعرف مستواهم. وشرحه يطلعك من الكلاس فاهم غصب. الدكتور متواجد طول اليوم بقروب الواتس او بالخاص. لو تجيه الفجر وتقوله عندي مشكلة بيقولك افتح تيمز نشوف. دايم يسوي هيلب سشنز من وقته الخاص قبل اي اختبار. افضل دكتور مر علي من دخولي للجامعة انصح فيه وبشدة.\n\nالتقييم النهائي : +++++++++++++A ويستاهل اكثر", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1533002-ics108", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/rashad-othman/183289/5", "user": "Omar-12232", "ts": 1639236950000, "tid": 183289, "pn": 5}}]}', 1639236950000, 1794766200, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-abubakermt-ics108', 'stk-abubakermt', 'ICS 108', 'doc', '{"docs": [{"id": "stk-dr-f183289", "n": "Dr. Rashad Othman", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ICS108 Term222\n\nالتحضير: متساهل لابعد درجة و يحضر عن طريق تسليمات اللاب.\n\nطريقة الشرح: ممتاز جدا و يحاول يربط المواضيع بالواقع قد ما يقدر. اذا ركزت معاه و فهمت محاضرته صدقني ما بتحتاج تذاكر شيء زيادة سواء للميد او الفاينل.\n\nالكويزات: بعضها متوسط و بعضها سهل للامانة، كل كويزاته كانت جزء اختيارات و جزء اوتبوت و جزء كود و غالبا الافرج كان حول الـ 30/40. لسبب ما اللاب تيست كان من اسهل ما يكون و بثواني تخلصه\n\nالصوت: واضح جدا و مفهوم، بس ملاحظة، الغرفة اللي كنا فيها كانت كبيرة شوي فحاول تجي بدري و تجلس بالمقدمة، الدكتور ما يقصر كان يحاول يمشي و بروح هنا و هناك عشان الكل يسمعه.\n\nالقريد النهائي: A+++++\n\nإضافات: رشاد و ما ادراك ما رشاد أفضل دكتور مر علي بلا منازع يهتم بالطالب اكثر منه، الدكتور جدا جدا جدا متعاون و وين ما تبيه راح تلقاه سواء تيمز الواتس ايميل مكتبه بأي مكان حرفيا و أي وقت حتى لو جيته الفجر بتلقاه، الدكتور خلوق جدا و يحب يمزح مع الطلاب و يحاول يحفظ اسماءهم و يعرف مستواهم و عمرك ما بتمل بمحاضراته، لو شفت اسمه نزل عنده بدون اي تفكير حتى لو اضطريت تغير الجدول كامل عشانه", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1536691-ics108", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/rashad-othman/183289/10", "user": "AbubakerMT", "ts": 1684168424000, "tid": 183289, "pn": 10}}]}', 1684168424000, 1794766200, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
